import{_ as o,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const h=JSON.parse('{"title":"Atalhos descritivos no menu superior","description":"","frontmatter":{"title":"Atalhos descritivos no menu superior","id":"eproc-atalhos-navbar-descritivos","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.1.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-atalhos-navbar-descritivos"}]]},"headers":[],"relativePath":"funcionalidades/eproc-atalhos-navbar-descritivos.md","filePath":"funcionalidades/eproc-atalhos-navbar-descritivos.md"}'),t={name:"funcionalidades/eproc-atalhos-navbar-descritivos.md"};function n(i,a,d,l,c,u){return e(),r("div",null,a[0]||(a[0]=[s('<h1 id="atalhos-descritivos-no-menu-superior" tabindex="-1">Atalhos descritivos no menu superior <a class="header-anchor" href="#atalhos-descritivos-no-menu-superior" aria-label="Permalink to &quot;Atalhos descritivos no menu superior&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Os atalhos rápidos do menu superior do eproc (Alt+1, Alt+2...) aparecem todos com o mesmo ícone genérico. Com este recurso, cada atalho ganha um ícone relacionado à rotina configurada nele e o nome da rotina ao lado, para você saber o que cada um abre sem precisar passar o mouse.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><ul><li><strong>eproc</strong>, menu superior, em todas as telas.</li><li><strong>eproc</strong>, tela de personalização do usuário (onde se escolhem as rotinas dos atalhos): ao lado de cada um dos três seletores de rotina aparece uma prévia de como o atalho ficará no menu.</li><li>Os atalhos repetidos no menu do perfil também ganham o ícone da rotina.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Configure os atalhos rápidos no próprio eproc, na tela de personalização do usuário. Enquanto escolhe a rotina, a prévia ao lado do seletor mostra o ícone e o nome que o atalho terá.</li><li>Volte a qualquer tela: o menu superior mostra os atalhos com o ícone e o nome da rotina.</li></ol><p>O ícone é escolhido automaticamente a partir do nome da rotina; não é preciso configurar nada.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mostrar apenas os ícones, sem o texto da rotina</td><td>desligada</td><td>Mantém só o ícone, ocupando menos espaço no menu.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Quando o nome da rotina não corresponde a nenhum ícone conhecido, o atalho fica com um ícone genérico.</li><li>Em janelas estreitas, o nome das rotinas pode não caber. Use a opção &quot;Mostrar apenas os ícones&quot;.</li></ul>',12)]))}const m=o(t,[["render",n]]);export{h as __pageData,m as default};
